window.setColor=setColor;window.closePanel=closePanel;window.saveGame=saveGame;window.equipStored=equipStored;window.openPanel=openPanel;window.goTitle=()=>{saveGame();gameOn=false;paused=true;$('panelScreen').classList.add('hidden');$('start').classList.remove('hidden')};
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function line(x1,y1,x2,y2,c,w=1){ctx.strokeStyle=c;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function poly(points,c){ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill()}
function drawPirate(x,y,dir,anim='idle',t=0,opts={}){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(dir,1);const s=opts.scale||1;ctx.scale(s,s);const attack=anim==='attack'||anim==='power',walk=anim==='walk'||anim==='run',roll=anim==='roll',jump=anim==='jump';let bob=Math.sin(t*(walk?15:3))*(walk?1.8:1.2);if(jump)bob=-3;let leg=Math.sin(t*14)*4*(walk?1:0), lean=anim==='run'?3:attack?2:0;
// soft foot shadow, angled 3/4 ground contact
ctx.globalAlpha=.28;ctx.fillStyle='#122329';ctx.beginPath();ctx.ellipse(0,0,14,4,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
if(roll){ctx.rotate(-.8);bob=4}
ctx.translate(lean,bob);
// cape / bandana tails trail against movement
poly([[-5,-38],[-12,-35],[-20,-30],[-17,-26],[-8,-31]],opts.band||player.custom.band);poly([[-2,-38],[-8,-39],[-17,-36],[-16,-33],[-6,-35]],'#843e3f');
// legs, trouser folds and boots
const stride=walk?leg:0;rect(-8,-19+Math.max(0,stride*.25),6,14+Math.max(0,-stride*.25),'#344759');rect(1,-19+Math.max(0,-stride*.25),6,14+Math.max(0,stride*.25),'#283746');rect(-8,-13,6,2,'#536171');rect(2,-13,5,2,'#536171');rect(-10,-6+Math.max(0,stride*.4),9,5,'#49362e');rect(1,-6+Math.max(0,-stride*.4),10,5,'#49362e');rect(-11,-3,11,2,'#201f24');rect(0,-3,12,2,'#201f24');
// sash swings in action
rect(-9,-25,19,5,opts.band||player.custom.band);rect(6,-26,5,3,'#e1ba70');poly([[7,-23],[14,-19+(walk?Math.sin(t*14)*2:0)],[11,-16],[7,-20]],opts.band||player.custom.band);
// torso outline then shirt, open jacket panels
rect(-11,-42,22,20,'#1b242c');rect(-10,-41,20,18,'#d7c6a2');rect(-9,-41,7,17,opts.vest||player.custom.vest);rect(3,-41,7,17,opts.vest||player.custom.vest);rect(-9,-39,3,12,shade(opts.vest||player.custom.vest,-24));rect(5,-39,3,12,shade(opts.vest||player.custom.vest,20));rect(-2,-39,4,14,'#e7d6b3');rect(-1,-33,2,2,'#6e4937');
// shoulder, arms and gloves
const armSwing=walk?Math.sin(t*14)*3:attack?6:0;rect(-13,-40,5,10,opts.vest||player.custom.vest);rect(-14,-32+armSwing,5,8,'#c98662');rect(-15,-27+armSwing,6,4,'#42312d');rect(8,-40,5,10,opts.vest||player.custom.vest);rect(9,-32-armSwing,5,8,'#d49770');rect(9,-27-armSwing,6,4,'#42312d');rect(-14,-28+armSwing,4,2,'#b67a5e');
// neck and face
rect(-4,-47,9,7,'#ad7059');rect(-7,-57,16,14,'#1a2028');rect(-6,-56,14,12,'#e3ac83');rect(-6,-54,2,5,'#c78567');rect(5,-55,2,5,'#c78567');rect(-4,-53,3,2,'#35262b');rect(3,-53,3,2,'#35262b');rect(-4,-54,3,1,opts.angry?'#241b20':'#573830');rect(3,-54,3,1,opts.angry?'#241b20':'#573830');if(opts.hit){rect(-4,-53,2,2,'#fff');rect(4,-53,2,2,'#fff')}else{rect(-3,-53,1,1,'#f8eee0');rect(4,-53,1,1,'#f8eee0')}rect(1,-48,2,1,'#995b4a');rect(-2,-46,5,1,opts.angry?'#a34e43':'#804a43');
// messy hair with silhouette and highlighted locks
rect(-8,-60,17,5,opts.hair||player.custom.hair);rect(-7,-63,4,5,opts.hair||player.custom.hair);rect(-2,-64,5,5,opts.hair||player.custom.hair);rect(4,-62,6,5,opts.hair||player.custom.hair);rect(-8,-59,3,4,opts.hair||player.custom.hair);rect(-5,-61,3,2,shade(opts.hair||player.custom.hair,32));rect(1,-63,3,2,shade(opts.hair||player.custom.hair,28));
// bandana across brow and tails
