ctx.restore();}
function shade(hex,amt){let n=parseInt(hex.slice(1),16);let r=clamp((n>>16)+amt,0,255),g=clamp(((n>>8)&255)+amt,0,255),b=clamp((n&255)+amt,0,255);return '#'+((1<<24)+(r<<16)+(g<<8)+b).toString(16).slice(1)}
function drawEnemy(e,x,y){ctx.save();ctx.translate(Math.round(x),Math.round(y));let f=e.hit>0;ctx.globalAlpha=e.alive?1:.4;ctx.fillStyle='#18302f';ctx.globalAlpha=.24;ctx.beginPath();ctx.ellipse(0,0,e.boss?19:13,4,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;const [name,shirt,accent]=enemyKinds[e.kind];let sc=e.boss?1.35:1;ctx.scale(sc,sc);rect(-7,-17,6,12,'#334454');rect(1,-17,6,12,'#263544');rect(-9,-6,9,5,'#49362e');rect(1,-6,10,5,'#49362e');rect(-10,-39,20,21,f?'#fff':shirt);rect(-9,-40,5,18,shade(shirt,-18));rect(3,-40,6,18,accent);rect(-6,-53,13,14,'#daa17c');rect(-7,-57,16,6,accent);rect(-5,-49,3,2,'#2c2528');rect(3,-49,3,2,'#2c2528');rect(-2,-44,5,1,'#713c37');rect(11,-32,3,17,'#6e4a36');rect(11,-33,3,19,'#c7d7d0');if(e.boss){rect(-22,-67,44,4,'#35252a');rect(-22,-67,44*clamp(e.hp/e.maxHp,0,1),4,'#e5584c')}ctx.restore()}
function drawTerrain(camX,camY){ctx.fillStyle='#4b9ca1';ctx.fillRect(0,0,W,H);let ox=-camX,oy=-camY;ctx.fillStyle='#277f91';ctx.fillRect(ox+0,oy+0,world.w,world.h); // island green core, sandy edge
ctx.fillStyle='#d5bd79';ctx.beginPath();ctx.ellipse(ox+world.w/2,oy+world.h/2,world.w*.49,world.h*.485,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#68a96f';ctx.beginPath();ctx.ellipse(ox+world.w/2,oy+world.h/2,world.w*.435,world.h*.425,0,0,Math.PI*2);ctx.fill();
