 function renderPanel(page){const box=$('panelContent');let content='';if(page==='character'){content=`<div class="tag">PIRATE PROFILE</div><h2>Character</h2><canvas id="preview" width="180" height="190" style="width:180px;height:190px;background:#416e68;border:2px solid #d5c997;image-rendering:pixelated"></canvas><div class="stats"><div class="stat">LEVEL <b>${player.level}</b></div><div class="stat">GOLD <b>${player.gold} ฿</b></div><div class="stat">MELEE <b>${player.melee}</b></div><div class="stat">SWORD <b>${player.sword}</b></div><div class="stat">DEFENSE <b>${player.defense}</b></div><div class="stat">FRUIT <b>${player.fruit?fruitData[player.fruit-1].name:'None'}</b></div></div><p>Customize your look</p><div class="row"><label>Hair <input type="color" value="${player.custom.hair}" onchange="setColor('hair',this.value)"></label><label>Vest <input type="color" value="${player.custom.vest}" onchange="setColor('vest',this.value)"></label><label>Bandana <input type="color" value="${player.custom.band}" onchange="setColor('band',this.value)"></label></div><div class="row"><button onclick="saveGame()">SAVE</button><button onclick="closePanel()">BACK</button></div>`;}else if(page==='inventory'){content=`<div class="tag">YOUR BELONGINGS</div><h2>Inventory</h2><p>Devil Fruits: ${inventory.length?inventory.map(i=>fruitData[i].name).join(' · '):'Your bag is empty.'}</p><div class="row">${inventory.map((i,n)=>`<button onclick="equipStored(${n})">EQUIP ${fruitData[i].name.split(' ')[0]}</button>`).join('')}</div><p>Gold: ${player.gold} ฿</p><button onclick="closePanel()">BACK</button>`;}else if(page==='map'){content=`<div class="tag">LOG POSE</div><h2>Tidebound Island</h2><canvas id="mapCanvas" width="300" height="190" style="width:min(300px,70vw);height:auto;background:#71a978;border:2px solid #d5c997"></canvas><p>Village · Forest · Sunlit Beach · Old Docks</p><button onclick="closePanel()">BACK</button>`;}else if(page==='settings'){content=`<div class="tag">OPTIONS</div><h2>Settings</h2><p>Day & night cycle <button onclick="timeOfDay=(timeOfDay+.25)%1">CHANGE TIME</button></p><p>Touch controls are ${innerWidth<innerHeight?'on':'available'} · Keyboard controls always active</p><button onclick="saveGame()">SAVE ADVENTURE</button><div class="row"><button onclick="closePanel()">BACK</button></div>`;}else{content=`<div class="tag">ADVENTURE PAUSED</div><h2>Take a breather</h2><div class="row"><button onclick="closePanel()">RESUME</button><button onclick="saveGame()">SAVE</button><button onclick="openPanel('character')">CHARACTER</button><button onclick="openPanel('settings')">SETTINGS</button><button onclick="goTitle()">TITLE</button></div>`;}box.innerHTML=content;if(page==='character')drawPreview();if(page==='map')drawMap();}
