55;background:#142b387a;pointer-events:auto;touch-action:none}.nub{position:absolute;width:44px;height:44px;border-radius:50%;left:32px;top:32px;background:#d9e7d799;border:2px solid #ffffffaa}.buttons{position:absolute;bottom:max(22px,env(safe-area-inset-bottom));right:12px;width:190px;height:164px;pointer-events:none}.act{position:absolute;width:52px;height:48px;border-radius:50%;border:2px solid #fff9;background:#152b3dcc;box-shadow:0 3px #0a1119aa;font-weight:bold;font-size:10px;pointer-events:auto;touch-action:none;padding:0}.act:active{background:#bd6d43}.a-atk{right:7px;bottom:44px;width:63px;height:60px;background:#9c4e3de0}.a-jump{right:77px;bottom:99px}.a-roll{right:77px;bottom:30px}.a-block{right:130px;bottom:81px}.a-s1{right:135px;bottom:20px}.a-s2{right:18px;bottom:111px}.a-ult{right:6px;bottom:0px;width:45px;height:42px;background:#72529ae0}.interact{position:absolute;left:50%;bottom:180px;transform:translateX(-50%);pointer-events:auto;background:#bb7939;display:none}.mobile-top{position:absolute;right:10px;top:76px;display:flex;gap:5px;pointer-events:auto}.mobile-top button{font-size:10px;padding:6px}.toast{position:fixed;top:19%;left:50%;transform:translateX(-50%);padding:10px 16px;background:#142c39ed;border:2px solid #e4d59a;z-index:4;font-size:13px;pointer-events:none;text-align:center;max-width:90vw}.pixel{font-family:inherit;letter-spacing:1px}
</style>
</head>
<body>
<canvas id="game" aria-label="Blox Fruits 2D game canvas" width="780" height="493" style="width: 780px; height: 493px;"></canvas>
<div class="topbar" id="hud"><div class="hudbox"><b id="levelText">LV. 1  •  WAVE 1</b><div class="meter"><i id="hpbar" style="width:100%"></i></div><div class="meter energy"><i id="enbar" style="width:100%"></i></div><span id="goldText">0 ฿  ·  0 XP</span></div><div class="hudbox" style="text-align:right"><span id="fruitLabel">NO FRUIT</span><br><button onclick="openPanel('character')">☰ MENU</button></div></div>
<div class="mobile-top"><button onclick="openPanel('inventory')">BAG</button><button onclick="openPanel('map')">MAP</button><button onclick="openPanel('pause')">Ⅱ</button></div>
<div class="touch-ui" id="touch"><div class="stick" id="stick"><div class="nub" id="nub"></div></div><div class="buttons"><button class="act a-atk" data-act="attack">ATK</button><button class="act a-jump" data-act="jump">JUMP</button><button class="act a-roll" data-act="roll">ROLL</button><button class="act a-block" data-act="block">BLOCK</button><button class="act a-s1" data-act="skill1">S1</button><button class="act a-s2" data-act="skill2">S2</button><button class="act a-ult" data-act="ult">ULT</button></div><button class="interact" id="interact">INTERACT</button></div>
<div class="screen" id="start"><div class="panel menu"><div class="tag">THE GRAND LINE • PIXEL ACTION RPG</div><h1>BLOX FRUITS<br><span style="font-size:.52em;color:#e3f2d5">2D · TIDEBOUND</span></h1><p>Sail into a bright new adventure. Defeat rival crews, claim a mysterious fruit, and become the legend of the sea.</p><div class="row"><button id="startBtn">▶ PLAY</button><button id="continueBtn">CONTINUE</button></div><p class="controls-hint">WASD / arrows move · J attack · K jump · L roll · I block · 1 / 2 skills · Space ultimate<br>Touch joystick and action buttons supported</p></div></div>
<div class="screen hidden" id="panelScreen"><div class="panel menu" id="panelContent"></div></div>
<div class="screen hidden" id="fruitScreen"><div class="panel menu"><div class="tag">A STRANGE FRUIT</div><h2 id="fruitTitle">Mystic Fruit</h2><p id="fruitDesc">Its skin spirals with an otherworldly glow.</p><div class="row"><button id="eatFruit">EAT</button><button id="storeFruit">STORE</button><button id="leaveFruit">LEAVE</button></div></div></div>
<div class="toast hidden" id="toast"></div>
<script>
(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d',{alpha:false});ctx.imageSmoothingEnabled=false;
const $=id=>document.getElementById(id); const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)); const rand=(a,b)=>a+Math.random()*(b-a); const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let W=480,H=800,scale=1,last=0,elapsed=0,gameOn=false,paused=true,mode='menu',timeOfDay=0.25,shake=0,hitStop=0,toastTimer=0,openFruit=null,keys={},touchMove={x:0,y:0},joystick=false;
const world={w:2200,h:1800};
const player={x:1090,y:990,vx:0,vy:0,dir:1,hp:100,maxHp:100,en:100,maxEn:100,level:1,xp:0,gold:0,melee:1,sword:1,defense:1,fruit:0,anim:'idle',animT:0,actionT:0,combo:0,attackCd:0,rollCd:0,invul:0,flash:0,face:'calm',air:0,jumpZ:0,jumpV:0,knock:0,blink:0,custom:{hair:'#352439',vest:'#31556a',band:'#ba5948'},target:null};
const names=['Ember','Frost','Volt','Magma','Gum'], fruitData=[{name:'Flame Fruit',color:'#ff6a42',glow:'#ffb13f',desc:'Kindles your spirit. Scorch enemies with fire and erupt in a blazing cyclone.'},{name:'Frost Fruit',color:'#8beaff',glow:'#cffcff',desc:'A crisp chill follows every step. Freeze foes, then shatter them.'},{name:'Spark Fruit',color:'#ffe45b',glow:'#fff7a1',desc:'Lightning-fast power. Chain arcs between nearby rivals.'},{name:'Magma Fruit',color:'#e95135',glow:'#ffa044',desc:'Heavy molten power leaves burning pools in its wake.'},{name:'Gum Fruit',color:'#ff73a9',glow:'#ffd0e1',desc:'Stretch and spring into elastic punches and bouncing shockwaves.'}];
let enemies=[],fruits=[],particles=[],projectiles=[],effects=[],decor=[],buildings=[],frozen=[],inventory=[];
const enemyKinds=[['Bandit','#9b5846','#e4b85c'],['Marine','#537b9f','#e9e9dc'],['Pirate','#724e87','#d68955'],['Captain','#a94c3e','#f2ca63']];
function resize(){const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);W=innerWidth<innerHeight?480:960;H=innerWidth<innerHeight?800:540;scale=Math.min(innerWidth/W,innerHeight/H);canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';ctx.imageSmoothingEnabled=false;}
addEventListener('resize',resize);resize();
function say(text){const t=$('toast');t.textContent=text;t.classList.remove('hidden');toastTimer=2.2;}
function startGame(load=false){$('start').classList.add('hidden');gameOn=true;paused=false;mode='play';enemies=[];fruits=[];particles=[];projectiles=[];effects=[];frozen=[];openFruit=null;if(load&&!localStorage.blox2d)load=false;if(load&&localStorage.blox2d){try{const s=JSON.parse(localStorage.blox2d);Object.assign(player,s.player);inventory=s.inventory||[];wave=s.wave||1;fruitIndex=s.fruitIndex||0;say('Save loaded — welcome back!')}catch{load=false;say('Save could not be read — starting fresh.')}}if(!load){Object.assign(player,{x:1090,y:990,vx:0,vy:0,hp:100,maxHp:100,en:100,maxEn:100,level:1,xp:0,gold:0,melee:1,sword:1,defense:1,fruit:0,anim:'idle',animT:0,actionT:0,combo:0,attackCd:0,rollCd:0,invul:0,flash:0,face:'calm',air:0,jumpZ:0,jumpV:0,custom:{hair:'#352439',vest:'#31556a',band:'#ba5948'}});inventory=[];wave=1;fruitIndex=0;say('Welcome to Tidebound Village!')}if(load)$('fruitLabel').textContent=player.fruit?fruitData[player.fruit-1].name.toUpperCase():'NO FRUIT';spawnWave(); }
let wave=1,fruitIndex=0,saveFlash=0;
function saveGame(){localStorage.setItem('blox2d',JSON.stringify({player:{x:player.x,y:player.y,hp:player.hp,maxHp:player.maxHp,en:player.en,maxEn:player.maxEn,level:player.level,xp:player.xp,gold:player.gold,melee:player.melee,sword:player.sword,defense:player.defense,fruit:player.fruit,custom:player.custom},inventory,wave,fruitIndex}));say('Adventure saved locally.');}
function spawnWave(){let count=Math.min(3+wave,12);for(let i=0;i<count;i++){const angle=i/count*Math.PI*2+rand(-.3,.3),r=rand(170,300),boss=wave%5===0&&i===0,kind=boss?3:(wave+i)%3;enemies.push({x:clamp(player.x+Math.cos(angle)*r,40,world.w-40),y:clamp(player.y+Math.sin(angle)*r,40,world.h-40),vx:0,vy:0,hp:boss?150:30+wave*5,maxHp:boss?150:30+wave*5,kind,boss,animT:rand(0,5),attack:rand(.3,1.7),hit:0,alive:true});}if(wave===1&&fruitIndex===0){dropFruit(player.x+rand(100,190),player.y+rand(-60,60),0);fruitIndex=1;}say(wave%5===0?'⚓ BOSS WAVE '+wave:'⚔ WAVE '+wave+' — '+count+' rivals');}
function dropFruit(x,y,type=Math.floor(Math.random()*fruitData.length)){fruits.push({x,y,vx:rand(-18,18),vy:-70,z:0,vz:100,type,phase:rand(0,6),alive:true});}
function initDecor(){decor=[];buildings=[];for(let i=0;i<200;i++){let x=rand(20,world.w-20),y=rand(20,world.h-20);decor.push({x,y,type:Math.random()<.54?'tree':Math.random()<.6?'grass':'flower',size:rand(.7,1.25),seed:Math.random()*9});}for(let i=0;i<15;i++){let x=250+(i%5)*360+rand(-40,40),y=300+Math.floor(i/5)*330+rand(-40,40);buildings.push({x,y,w:rand(90,125),h:rand(72,92),roof:['#b95c45','#647e91','#8b6550'][i%3],type:i%4===0?'shop':'home'});}}
initDecor();
function doAction(a){if(!gameOn||paused)return;const now=performance.now()/1000;if(a==='attack'&&player.attackCd<=0){player.combo=player.combo%3+1;player.anim='attack';player.actionT=.38;player.attackCd=.25;player.face='angry';hitStop=.07;shake=3;let hit=false;for(const e of enemies){if(!e.alive||dist(player,e)>72)continue;if((e.x-player.x)*player.dir < -20)continue;e.hp-=14+player.sword*5;e.hit=.22;e.vx=player.dir*220;e.vy=-70;hit=true;particlesBurst(e.x,e.y-18,'#ffe68b',10);if(e.hp<=0)killEnemy(e);}if(hit)say(['Slash!','Cross cut!','Finisher!'][player.combo-1]);}
if(a==='jump'&&player.air<=0){player.air=1;player.jumpZ=0;player.jumpV=250;player.anim='jump';player.actionT=.4;particlesBurst(player.x,player.y,'#d7e5b4',5)}
if(a==='roll'&&player.rollCd<=0){player.anim='roll';player.actionT=.48;player.invul=.52;player.rollCd=.8;player.vx=player.dir*330;particlesBurst(player.x,player.y,'#c9d4c0',6)}
if(a==='block'){player.anim='block';player.actionT=.35;player.face='angry'}
if(a==='skill1'||a==='skill2'||a==='ult'){if(!player.fruit){say('Find and eat a Devil Fruit first!');return}const ult=a==='ult',cost=ult?70:25;if(player.en<cost){say('Not enough energy!');return}player.en-=cost;castPower(a,ult)} }
function castPower(a,ult){const f=fruitData[player.fruit-1];player.anim='power';player.actionT=ult?1.8:.65;player.face='angry';const power=ult?38:22,range=ult?210:145;effects.push({x:player.x,y:player.y,type:'burst',color:f.color,t:ult?1.6:.6,max:ult?1.6:.6,r:range,fruit:player.fruit});let n=0;for(const e of enemies){if(e.alive&&dist(player,e)<range){e.hp-=power;e.hit=.3;e.vx=(e.x-player.x)/(dist(player,e)||1)*(ult?270:190);e.vy=(e.y-player.y)/(dist(player,e)||1)*100;particlesBurst(e.x,e.y-18,f.glow,ult?16:8);if(player.fruit===2)e.frozen=ult?2.5:1.2;if(e.hp<=0)killEnemy(e);n++;if(player.fruit===3&&a!=='ult'&&n<3)continue;}}if(player.fruit===0){}if(player.fruit===1||player.fruit===4)effects.push({x:player.x+player.dir*75,y:player.y+20,type:'pool',color:f.color,t:4,max:4,r:70});if(player.fruit===2)frozen.push({x:player.x,y:player.y,r:90,t:4});if(player.fruit===3){for(let i=0;i<Math.min(n,4);i++)effects.push({x:player.x+rand(-140,140),y:player.y+rand(-100,100),type:'zap',color:f.color,t:.4,max:.4,r:8});}if(player.fruit===5){player.vx=player.dir*(ult?390:260)}say(ult?'ULTIMATE!  '+f.name+' unleashed!':f.name+' skill!');shake=ult?7:4;}
function killEnemy(e){e.alive=false;player.gold+=e.boss?150:12+Math.floor(wave*1.5);player.xp+=e.boss?150:25;particlesBurst(e.x,e.y-16,'#ffd978',14);if(Math.random()<.16||e.boss)dropFruit(e.x,e.y,Math.floor(Math.random()*fruitData.length));if(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.maxHp+=12;player.hp=player.maxHp;player.maxEn+=5;player.en=player.maxEn;say('LEVEL UP! Now level '+player.level+' · stats improved');}if(enemies.every(x=>!x.alive)){wave++;setTimeout(()=>{if(gameOn)spawnWave()},800)}}
function particlesBurst(x,y,color,n){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=rand(30,170);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-35,t:rand(.22,.7),life:rand(.22,.7),color,size:rand(2,5)})}}
function nearestFruit(){let f=null,d=52;for(const x of fruits)if(x.alive&&dist(player,x)<d){f=x;d=dist(player,x)}return f;}
function showFruit(f){openFruit=f;const data=fruitData[f.type];$('fruitTitle').textContent=data.name;$('fruitDesc').textContent=data.desc;$('fruitScreen').classList.remove('hidden');paused=true;mode='fruit';}
function fruitChoice(choice){if(!openFruit)return;if(choice==='eat'){player.fruit=openFruit.type+1;$('fruitLabel').textContent=fruitData[openFruit.type].name.toUpperCase();say('You ate the '+fruitData[openFruit.type].name+'!');}else if(choice==='store'){inventory.push(openFruit.type);say(fruitData[openFruit.type].name+' stored in your bag.')}openFruit.alive=false;openFruit=null;$('fruitScreen').classList.add('hidden');paused=false;mode='play';}
$('eatFruit').onclick=()=>fruitChoice('eat');$('storeFruit').onclick=()=>fruitChoice('store');$('leaveFruit').onclick=()=>{openFruit=null;$('fruitScreen').classList.add('hidden');paused=false;mode='play'};
function openPanel(page){if(!gameOn)return;paused=true;mode=page;$('panelScreen').classList.remove('hidden');renderPanel(page)}
function closePanel(){ $('panelScreen').classList.add('hidden');paused=false;mode='play'}
function renderPanel(page){const box=$('panelContent');let content='';if(page==='character'){content=`<div class="tag">PIRATE PROFILE</div><h2>Character</h2><canvas id="preview" width="180" height="190" style="width:180px;height:190px;background:#416e68;border:2px solid #d5c997;image-rendering:pixelated"></canvas><div class="stats"><div class="stat">LEVEL <b>${player.level}</b></div><div class="stat">GOLD <b>${player.gold} ฿</b></div><div class="stat">MELEE <b>${player.melee}</b></div><div class="stat">SWORD <b>${player.sword}</b></div><div class="stat">DEFENSE <b>${player.defense}</b></div><div class="stat">FRUIT <b>${player.fruit?fruitData[player.fruit-1].name:'None'}</b></div></div><p>Customize your look</p><div class="row"><label>Hair <input type="color" value="${player.custom.hair}" onchange="setColor('hair',this.value)"></label><label>Vest <input type="color" value="${player.custom.vest}" onchange="setColor('vest',this.value)"></label><label>Bandana <input type="color" value="${player.custom.band}" onchange="setColor('band',this.value)"></label></div><div class="row"><button onclick="saveGame()">SAVE</button><button onclick="closePanel()">BACK</button></div>`;}else if(page==='inventory'){content=`<div class="tag">YOUR BELONGINGS</div><h2>Inventory</h2><p>Devil Fruits: ${inventory.length?inventory.map(i=>fruitData[i].name).join(' · '):'Your bag is empty.'}</p><div class="row">${inventory.map((i,n)=>`<button onclick="equipStored(${n})">EQUIP ${fruitData[i].name.split(' ')[0]}</button>`).join('')}</div><p>Gold: ${player.gold} ฿</p><button onclick="closePanel()">BACK</button>`;}else if(page==='map'){content=`<div class="tag">LOG POSE</div><h2>Tidebound Island</h2><canvas id="mapCanvas" width="300" height="190" style="width:min(300px,70vw);height:auto;background:#71a978;border:2px solid #d5c997"></canvas><p>Village · Forest · Sunlit Beach · Old Docks</p><button onclick="closePanel()">BACK</button>`;}else if(page==='settings'){content=`<div class="tag">OPTIONS</div><h2>Settings</h2><p>Day & night cycle <button onclick="changeTime()">CHANGE TIME</button></p><p>Touch controls are ${innerWidth<innerHeight?'on':'available'} · Keyboard controls always active</p><button onclick="saveGame()">SAVE ADVENTURE</button><div class="row"><button onclick="closePanel()">BACK</button></div>`;}else{content=`<div class="tag">ADVENTURE PAUSED</div><h2>Take a breather</h2><div class="row"><button onclick="closePanel()">RESUME</button><button onclick="saveGame()">SAVE</button><button onclick="openPanel('character')">CHARACTER</button><button onclick="openPanel('settings')">SETTINGS</button><button onclick="goTitle()">TITLE</button></div>`;}box.innerHTML=content;if(page==='character')drawPreview();if(page==='map')drawMap();}
function equipStored(n){let type=inventory.splice(n,1)[0];player.fruit=type+1;$('fruitLabel').textContent=fruitData[type].name.toUpperCase();say(fruitData[type].name+' equipped!');renderPanel('inventory')}
function setColor(key,value){player.custom[key]=value;drawPreview()}
window.setColor=setColor;window.changeTime=()=>timeOfDay=(timeOfDay+.25)%1;window.closePanel=closePanel;window.saveGame=saveGame;window.equipStored=equipStored;window.openPanel=openPanel;window.goTitle=()=>{saveGame();gameOn=false;paused=true;$('panelScreen').classList.add('hidden');$('start').classList.remove('hidden')};
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function line(x1,y1,x2,y2,c,w=1){ctx.strokeStyle=c;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function poly(points,c){ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill()}
function drawPirate(x,y,dir,anim='idle',t=0,opts={}){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(dir,1);const s=opts.scale||1;ctx.scale(s,s);const attack=anim==='attack'||anim==='power',walk=anim==='walk'||anim==='run',roll=anim==='roll',jump=anim==='jump';let bob=Math.sin(t*(walk?15:3))*(walk?1.8:1.2);if(jump)bob=-3;let leg=Math.sin(t*14)*4*(walk?1:0), lean=anim==='run'?3:attack?2:0;
// soft foot shadow, angled 3/4 ground contact
ctx.globalAlpha=.28;ctx.fillStyle='#122329';ctx.beginPath();ctx.ellipse(0,0,14,4,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
if(roll){ctx.rotate(-.8);bob=4}
ctx.translate(lean,bob);
// cape / bandana tails trail against movement
poly([[-5,-38],[-12,-35],[-20,-30],[-17,-26],[-8,-31]],opts.band||player.custom.band);poly([[-2,-38],[-8,-39],[-17,-36],[-16,-33],[-6,-35]],'#843e3f');
// legs, trouser folds and boots
const stride=walk?leg:0;rect(-8,-19+Math.max(0,stride*.25),6,14+Math.max(0,-stride*.25),'#344759');rect(1,-19+Math.max(0,-stride*.25),6,14+Math.max(0,stride*.25),'#283746');rect(-8,-13,6,2,'#536171');rect(2,-13,5,2,'#536171');rect(-10,-6+Math.max(0,stride*.4),9,5,'#49362e');rect(1,-6+Math.max(0,-stride*.4),10,5,'#49362e');rect(-11,-3,11,2,'#201f24');rect(0,-3,12,2,'#201f24');
// sash swings in action
rect(-9,-25,19,5,opts.band||player.custom.band);rect(6,-26,5,3,'#e1ba70');poly([[7,-23],[14,-19+(walk?Math.sin(t*14)*2:0)],[11,-16],[7,-20]],opts.band||player.custom.band);
// torso outline then shirt, open jacket panels
